<?php
require __DIR__.'/includes/bootstrap.php';require_login();$page_title='Messages';$st=db()->prepare("SELECT c.id,c.updated_at,p.title, CASE WHEN c.buyer_id=? THEN s.name ELSE b.name END AS other_name FROM conversations c JOIN products p ON p.id=c.product_id JOIN users b ON b.id=c.buyer_id JOIN users s ON s.id=c.seller_id WHERE c.buyer_id=? OR c.seller_id=? ORDER BY c.updated_at DESC");$uid=current_user()['id'];$st->execute([$uid,$uid,$uid]);$items=$st->fetchAll();include __DIR__.'/includes/header.php';?>
<div class="section-heading"><div><span class="eyebrow">YOUR INBOX</span><h1>Messages</h1></div></div><div class="conversation-list"><?php foreach($items as $c): ?><a href="<?= e(url('chat.php?id='.$c['id'])) ?>"><strong><?= e($c['title']) ?></strong><span>Conversation with <?= e($c['other_name']) ?></span><small><?= e($c['updated_at']) ?></small></a><?php endforeach; ?><?php if(!$items): ?><div class="empty">No conversations yet. Open a listing and contact its seller.</div><?php endif; ?></div>
<?php include __DIR__.'/includes/footer.php'; ?>
